package com.mathengine.engine;
import java.math.BigDecimal;import java.math.MathContext;import java.math.RoundingMode;
/** Safe recursive-descent calculator. */
public final class CalculatorEngine {
private static final MathContext MC=new MathContext(14,RoundingMode.HALF_UP);private String input;private int pos;private boolean degrees=true;
public void setDegrees(boolean value){degrees=value;}
public String evaluate(String expression){input=expression.replace('×','*').replace('÷','/').replace('−','-').replace("π",Double.toString(Math.PI));pos=0;double result=expression();spaces();if(pos!=input.length())throw new IllegalArgumentException("Unexpected token");if(!Double.isFinite(result))throw new ArithmeticException("Result is not finite");if(Math.abs(result)<1e-12)result=0;return BigDecimal.valueOf(result).round(MC).stripTrailingZeros().toPlainString();}
private double expression(){double x=term();while(true){spaces();if(eat('+'))x+=term();else if(eat('-'))x-=term();else return x;}}
private double term(){double x=power();while(true){spaces();if(eat('*'))x*=power();else if(eat('/')){double d=power();if(d==0)throw new ArithmeticException("Division by zero");x/=d;}else if(eat('%'))x%=power();else return x;}}
private double power(){double x=unary();spaces();if(eat('^'))x=Math.pow(x,power());return x;}
private double unary(){spaces();if(eat('+'))return unary();if(eat('-'))return -unary();return atom();}
private double atom(){spaces();if(eat('(')){double x=expression();spaces();require(')');return x;}if(pos<input.length()&&Character.isLetter(input.charAt(pos))){int start=pos;while(pos<input.length()&&Character.isLetter(input.charAt(pos)))pos++;String fn=input.substring(start,pos).toLowerCase();spaces();if(fn.equals("pi"))return Math.PI;if(fn.equals("e"))return Math.E;require('(');double a=expression();spaces();require(')');double angle=degrees?Math.toRadians(a):a;switch(fn){case "sin":return Math.sin(angle);case "cos":return Math.cos(angle);case "tan":return Math.tan(angle);case "asin":return convertAngle(Math.asin(a));case "acos":return convertAngle(Math.acos(a));case "atan":return convertAngle(Math.atan(a));case "sqrt":if(a<0)throw new ArithmeticException("Invalid square root");return Math.sqrt(a);case "ln":if(a<=0)throw new ArithmeticException("Log domain error");return Math.log(a);case "log":if(a<=0)throw new ArithmeticException("Log domain error");return Math.log10(a);case "abs":return Math.abs(a);case "floor":return Math.floor(a);case "ceil":return Math.ceil(a);default:throw new IllegalArgumentException("Unknown function: "+fn);}}
int start=pos;boolean dot=false;while(pos<input.length()){char c=input.charAt(pos);if(Character.isDigit(c))pos++;else if(c=='.'&&!dot){dot=true;pos++;}else break;}if(start==pos)throw new IllegalArgumentException("Number expected");return Double.parseDouble(input.substring(start,pos));}
private double convertAngle(double x){return degrees?Math.toDegrees(x):x;}private void spaces(){while(pos<input.length()&&Character.isWhitespace(input.charAt(pos)))pos++;}private boolean eat(char c){if(pos<input.length()&&input.charAt(pos)==c){pos++;return true;}return false;}private void require(char c){if(!eat(c))throw new IllegalArgumentException("Expected '"+c+"'");}
}
